package com.vandorlabs.ui;
public final class SynthesisDialogTest {
 public static void main(String[] args){for(boolean compact:new boolean[]{false,true}){SynthesisDialog.Layout d=new SynthesisDialog.Layout(compact);for(int i=0;i<43;i++){int x=d.slotX(i),y=d.slotY(i);if(x<0||y<0||x+16>d.width||y+16>d.height)throw new AssertionError("Slot bounds "+i);for(int j=0;j<i;j++)if(Math.abs(x-d.slotX(j))<18&&Math.abs(y-d.slotY(j))<18)throw new AssertionError("Slot overlap "+i+"/"+j);}if(d.machineX(2)+18!=d.machineX(4)||d.machineX(4)+18!=d.machineX(5)||d.machineX(5)+18!=d.machineX(6))throw new AssertionError("Append-only bank order");if(d.progressX()<=d.machineX(0)+16||d.progressX()+d.progressWidth()>=d.machineX(1)-1)throw new AssertionError("Progress between input/output");if(SynthesisDialog.layout(compact?320:400,compact?240:340).compact!=compact)throw new AssertionError("Shared viewport selection");if(compact&&(d.width>320||d.height>240))throw new AssertionError("Minimum GUI");}System.out.println("SynthesisDialogTest PASS full/compact43slots/appendOnlyBanks");}
}
